const ll mod = 1e9 + 7;
ll max_p = 1e9 + 100;
typedef unsigned long long ull;
#if _LOCAL
#include <__msvc_int128.hpp>
using big_unsigned = _Unsigned128;
#else
using big_unsigned = __uint128_t;
#endif
struct H {
	ull x; H(ull x = 0) : x(x) {}
	H operator+(H o) { return x + o.x + (x + o.x < x); }
	H operator-(H o) { return *this + ~o.x; }
	H operator*(H o) {
		auto m = (big_unsigned)x * o.x;
		return H((ull)m) + (ull)(m >> 64);
	}


	ull get() const { return x + !~x; }
	bool operator==(H o) const { return get() == o.get(); }
	bool operator!=(H o) const { return get() != o.get(); }
	bool operator<(H o) const { return get() < o.get(); }
};
static const H C = (ll)1e11 + 3; // (order ~ 3e9; random also ok)
static const H C_inv = 1344427150348436797; // (order ~ 3e9; random also ok)
ll binpow(ll a, ll b)
{
	ll ret = 1;
	ll m = a;
	while (b)
	{
		if (b % 2) ret = (ret * m) % mod;
		m = (m * m) % mod;
		b /= 2;
	}

	return ret;
}

