H binpow_c(ll b)
{
	H ret = 1;
	H m = C;
	int i = 0;
	while (b)
	{
		ret = ret * smallbases[i][b % (1 << 8)];
		i++;
		b >>= 8;
	}

	return ret;
}

struct hash_t
{
	H val;

	hash_t()
	{
		val = 0;
	}

	hash_t(ull x)
	{
		val = x;
	}

	hash_t(H x) : val(x) {}

	hash_t operator+(const hash_t& other)
	{
		return val + other.val;
	}

	hash_t operator*(const hash_t& other)
	{
		return val * other.val;
	}

	hash_t operator-(const hash_t& other)
	{
		return val - other.val;
	}

	static hash_t hash_at(ll r)
	{
		return binpow_c(r);
	}

	bool operator!=(const hash_t& other)
	{
		return val != other.val;
	}
};
const hash_t UNITH = hash_t();
const int LAZY_ZERO = 1;
const int LAZY_ONE = 2;

hash_t hash_pref(ll r)
{
	hash_t ret = hash_t::hash_at(r + 1);
	ret = ret - hash_t(1);
	ret = ret * C_inv;
	return ret;
}

hash_t hash_interval(ll l, ll r)
{
	hash_t ret = hash_pref(r);

	if (l)
	{
		hash_t lp = hash_pref(l - 1);
		ret = ret - lp;
	}
	return ret;
}

struct Node
{
	Node* lc = 0, * rc = 0;
	ll num_ones = 0;
	hash_t h = UNITH;
	char lazy_value = 0;

	ll get_ones(Node* x)
	{
		if (!x) return 0;
		return x->num_ones;
	}
	hash_t get_h(Node* x)
	{
		if (!x) return UNITH;
		return x->h;
	}

	Node(ll l, ll r, char lazyval)
	{
		if (lazyval == LAZY_ZERO)
		{
			//lazyval = LAZY_ZERO;
		}
		else
		{
			//Dassert(l==r);
			num_ones = r - l + 1;
			h = hash_interval(l, r);
		}
		lazy_value = lazyval;
	}

	void merge_children()
	{
		num_ones = get_ones(lc) + get_ones(rc);
		hash_t lh = get_h(lc);
		hash_t rh = get_h(rc);
		h = lh + rh;
	}

	Node(Node* lc, Node* rc) : lc(lc), rc(rc)
	{
		merge_children();
	}

	Node() {}

	bool monotone_one(ll l, ll r)
	{
		return num_ones == r - l + 1;
	}

	bool monotone_zero()
	{
		return num_ones == 0;
	}

	void push(ll l, ll r)
	{
		if (l == r) return;
		if (lazy_value == 0) return;
		ll mid = (l + r) / 2;
		lc = new Node(l, mid, lazy_value);
		rc = new Node(mid + 1, r, lazy_value);
		merge_children();
		lazy_value = 0;
	}

	ll get_v(ll l, ll r)
	{
		if (monotone_zero()) return 0;
		push(l, r);
		if (monotone_one(l, r))
		{
			ll ret = binpow(2, r + 1);
			ret -= 1;
			if (l)
			{
				ret -= binpow(2, l);
				ret++;
			}
			ret %= mod;
			ret += mod;
			ret %= mod;
			return ret;
		}
		ll mid = (l + r) / 2;
		ll ret = 0;
		if (lc) ret += lc->get_v(l, mid);
		if (rc) ret = (ret + rc->get_v(mid + 1, r)) % mod;
		return ret;
	}

	Node* set_to(ll l, ll r, ll ql, ll qr, int v)
	{
		if (r < ql || l > qr) return this;
		if (l >= ql && r <= qr)
		{
			return new Node(l, r, v);
		}
		ll mid = (l + r) / 2;
		push(l, r);
		if (!lc) lc = new Node();
		if (!rc) rc = new Node();
		return new Node(lc->set_to(l, mid, ql, qr, v), rc->set_to(mid + 1, r, ql, qr, v));
	}

	ll get_last(ll l, ll r)
	{
		if (!rc) return lazy_value == LAZY_ONE;
		if (l == r) return num_ones;
		return rc->get_last((l + r) / 2 + 1, r);
	}
};



bool monotone_zero(Node* x)
{
	if (!x) return true;
	return x->num_ones == 0;
}

ll internal_search_zero(Node* x, ll l, ll r, ll ql, ll qr) // invariant: l>=ql&&r<=qr
{
	if (!x) return l;
	Dassert(!x->monotone_one(l, r));
	Dassert(l >= ql && r <= qr);
	if (l == r)
	{
		Dassert(monotone_zero(x));
		return l;
	}
	x->push(l, r);
	if (monotone_zero(x->lc)) return l;
	Dassert(x->lc);
	ll mid = (l + r) / 2;
	if (!x->lc->monotone_one(l, mid)) return internal_search_zero(x->lc, l, mid, ql, qr);
	if (!x->rc) return mid + 1;
	return internal_search_zero(x->rc, mid + 1, r, ql, qr);
}

ll leftmost_zero(Node* x, ll l, ll r, ll ql, ll qr)
{
	if (r < ql || l > qr) return -1;
	if (!x) return max(l, ql);
	if (l == r)
	{
		if (x->monotone_zero()) return l;
		return -1;
	}
	x->push(l, r);
	ll mid = (l + r) / 2;
	if (l >= ql && r <= qr)
	{
		if (x->monotone_one(l, r)) return -1;
		return internal_search_zero(x, l, r, ql, qr);
	}
	ll v = leftmost_zero(x->lc, l, mid, ql, qr);
	if (v != -1) return v;
	return leftmost_zero(x->rc, mid + 1, r, ql, qr);
}

ll internal_search_one(Node* x, ll l, ll r, ll ql, ll qr) // invariant: l>=ql&&r<=qr
{
	//assert(!(l == 12 && r == 14 && x->h.first== 718361438));
	Dassert(x);
	Dassert(!x->monotone_zero());
	Dassert(l >= ql && r <= qr);
	if (x->monotone_one(l, r))
	{
		return l;
	}
	x->push(l, r);
	ll mid = (l + r) / 2;
	if (x->lc && !x->lc->monotone_zero()) return internal_search_one(x->lc, l, mid, ql, qr);
	Dassert(x->rc);
	Dassert(!x->rc->monotone_zero());
	return internal_search_one(x->rc, mid + 1, r, ql, qr);
}

ll leftmost_one(Node* x, ll l, ll r, ll ql, ll qr)
{
	if (r < ql || l > qr) return -1;
	if (!x) return -1;
	if (l == r)
	{
		if (x->monotone_one(l, r)) return l;
		return -1;
	}
	x->push(l, r);
	ll mid = (l + r) / 2;
	if (l >= ql && r <= qr)
	{
		if (x->monotone_zero()) return -1;
		return internal_search_one(x, l, r, ql, qr);
	}
	ll v = leftmost_one(x->lc, l, mid, ql, qr);
	if (v != -1) return v;
	return leftmost_one(x->rc, mid + 1, r, ql, qr);
}

hash_t get_h(Node* x)
{
	if (!x) return UNITH;
	return x->h;
}

bool isgreater(Node* a, Node* b, ll l, ll r) // is a greater than b?
{
	if (!a || !b)
	{
		if (!a) return false;
		Dassert(!b);
		return !monotone_zero(a);
	}
	if (l == r)
	{
		return a->num_ones;
	}
	ll mid = (l + r) / 2;
	a->push(l, r);
	b->push(l, r);

	if (get_h(a->rc) != get_h(b->rc)) return isgreater(a->rc, b->rc, mid + 1, r);
	return isgreater(a->lc, b->lc, l, mid);
}

void Print(Node* x, ll l, ll r)
{
	if (l == r)
	{
		cout << x->num_ones;
		return;
	}
	if (!x->lc) x->lc = new Node();
	if (!x->rc) x->rc = new Node();
	x->push(l, r);
	ll mid = (l + r) / 2;
	Print(x->lc, l, mid);
	Print(x->rc, mid + 1, r);
}

struct BigNum
{
	Node* node;
	BigNum() : node(new Node()) {}
	BigNum(Node* x) : node(x) {}

	BigNum sub(ll p)
	{
		ll one_ind = leftmost_one(node, 0, max_p - 1, p, max_p - 1);
		Node* ret = node;
		if (one_ind == -1)
		{
			ret = ret->set_to(0, max_p - 1, p, max_p - 1, LAZY_ONE);
		}
		else
		{
			ret = ret->set_to(0, max_p - 1, p, one_ind - 1, LAZY_ONE);
			Dassert(ret);
			ret = ret->set_to(0, max_p - 1, one_ind, one_ind, LAZY_ZERO);
			Dassert(ret);
		}
		return BigNum(ret);
	}

	BigNum operator+(ll p)
	{
		if (p < 0) return sub(-p);
		//Print(node, 0, max_p - 1);
		//cout << '\n';
		ll zero_ind = leftmost_zero(node, 0, max_p - 1, p, max_p - 1);
		Node* ret = node;
		if (zero_ind == -1)
		{
			ret = ret->set_to(0, max_p - 1, p, max_p - 1, LAZY_ZERO);
		}
		else
		{
			ret = ret->set_to(0, max_p - 1, p, zero_ind - 1, LAZY_ZERO);
			Dassert(ret);
			ret = ret->set_to(0, max_p - 1, zero_ind, zero_ind, LAZY_ONE);
			Dassert(ret);
		}
		return BigNum(ret);
	}

	void chmax(const BigNum& other)
	{
		if (other.node->get_last(0, max_p - 1) && !node->get_last(0, max_p - 1)) return;
		if ((!other.node->get_last(0, max_p - 1) && node->get_last(0, max_p - 1)) || isgreater(other.node, node, 0, max_p - 1))
		{
			node = other.node;
		}
	}

	ll print()
	{
		ll ret = node->get_v(0, max_p - 1);
		if (node->get_last(0, max_p - 1))
		{
			ret -= binpow(2, max_p - 1);
			ret -= binpow(2, max_p - 1);
			ret %= mod;
			ret += mod;
			ret %= mod;
		}
		return ret;
	}
};

